import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Security and Permissions","description":"","frontmatter":{"title":"Security and Permissions"},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1793266312000}`),a={name:`guide/security.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_12-security-and-permissions" tabindex="-1">12. Security and Permissions <a class="header-anchor" href="#_12-security-and-permissions" aria-label="Permalink to “12. Security and Permissions”">​</a></h1><h2 id="_12-1-least-privilege" tabindex="-1">12.1 Least privilege <a class="header-anchor" href="#_12-1-least-privilege" aria-label="Permalink to “12.1 Least privilege”">​</a></h2><p>Custos may need to manage services, the network and system processes, so the following must be clearly distinguished:</p><ul><li>Read-only probe permissions.</li><li>Ordinary recovery permissions.</li><li>Network configuration permissions.</li><li>Service management permissions.</li><li>System reboot permissions.</li><li>Notification sending permissions.</li></ul><p>It is never acceptable to hand every plugin full system permissions by default just for convenience.</p><h2 id="_12-2-high-risk-actions" tabindex="-1">12.2 High-risk actions <a class="header-anchor" href="#_12-2-high-risk-actions" aria-label="Permalink to “12.2 High-risk actions”">​</a></h2><p>High-risk actions include:</p><ul><li>Resetting network interfaces.</li><li>Modifying the routing table.</li><li>Modifying the firewall.</li><li>Switching proxy configuration.</li><li>Rebooting the entire device.</li><li>Modifying authentication information.</li></ul><p>Every action must have:</p><ul><li>A risk declaration.</li><li>Permission requirements.</li><li>A scope of effect.</li><li>A timeout.</li><li>Concurrency control.</li><li>Result verification.</li><li>Failure handling.</li><li>Optional rollback or compensation.</li></ul><p>In the first version, the administrator may explicitly allow high-risk actions in configuration.</p><h2 id="_12-3-safety-when-recovering-from-network-interruption" tabindex="-1">12.3 Safety when recovering from network interruption <a class="header-anchor" href="#_12-3-safety-when-recovering-from-network-interruption" aria-label="Permalink to “12.3 Safety when recovering from network interruption”">​</a></h2><p>Recovering the network requires special caution:</p><ul><li>Do not conclude the underlying network failed just because the proxy failed.</li><li>Do not conclude the proxy is down from an HTTP 407.</li><li>Do not attribute every connection timeout to DNS.</li><li>Do not blindly reset the network while dependency state is unknown.</li><li>Do not repeatedly restart network interfaces back to back.</li><li>Do not treat a broken remote management channel as justification for unlimited retries.</li></ul><p>When evidence is insufficient, record the reason and escalate the alert instead of trying every recovery action.</p><hr>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};